import java.util.*;

public class Main {
    static final int NEG = -1_000_000_000;
    static int size;
    static int[] tree;

    static int query(int l, int r) { // max over [l, r)
        int res = NEG;
        for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
            if ((l & 1) == 1) res = Math.max(res, tree[l++]);
            if ((r & 1) == 1) res = Math.max(res, tree[--r]);
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int m = r.nextInt(), n = r.nextInt();
        long[] initial = new long[m], target = new long[n];
        for (int i = 0; i < m; i++) initial[i] = r.nextLong();
        for (int i = 0; i < n; i++) target[i] = r.nextLong();
        // Target values are distinct: sorted (value, index) keys replace a hash map.
        final long off = 1_000_000_000L;
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = ((target[i] + off) << 18) | i;
        Arrays.sort(key);
        long[] vals = new long[n];
        for (int i = 0; i < n; i++) vals[i] = (key[i] >> 18) - off;
        int[] before = new int[n];
        int last = -1;
        for (int i = 0; i < n; i++) { before[i] = last; if (target[i] <= 0) last = i; }
        size = 1;
        while (size < n) size *= 2;
        tree = new int[2 * size];
        Arrays.fill(tree, NEG);
        for (long v : initial) {
            int found = Arrays.binarySearch(vals, v);
            if (found < 0) continue;
            int q = (int) (key[found] & ((1 << 18) - 1)), b = before[q];
            int best = query(Math.max(0, b), q);
            if (b < 0) best = Math.max(best, 0);
            if (best < 0) continue;
            int at = q + size, value = best + 1;
            if (tree[at] >= value) continue;
            tree[at] = value;
            for (at >>= 1; at > 0; at >>= 1) tree[at] = Math.max(tree[2 * at], tree[2 * at + 1]);
        }
        int matched = query(Math.max(0, last), n);
        if (last < 0) matched = Math.max(matched, 0);
        System.out.println(matched >= 0 ? n - matched : -1);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

