const neg = -1000000000

func main() {
	m, n := readInt(), readInt()
	initial := make([]int, m)
	target := make([]int, n)
	for i := range initial {
		initial[i] = readInt()
	}
	for i := range target {
		target[i] = readInt()
	}
	position := make(map[int]int, n)
	for i, v := range target {
		position[v] = i
	}
	before := make([]int, n)
	last := -1
	for i, v := range target {
		before[i] = last
		if v <= 0 {
			last = i
		}
	}
	size := 1
	for size < n {
		size *= 2
	}
	tree := make([]int, 2*size)
	for i := range tree {
		tree[i] = neg
	}
	query := func(l, r int) int { // max over [l, r)
		res := neg
		for l, r = l+size, r+size; l < r; l, r = l>>1, r>>1 {
			if l&1 == 1 {
				res = max(res, tree[l])
				l++
			}
			if r&1 == 1 {
				r--
				res = max(res, tree[r])
			}
		}
		return res
	}
	for _, v := range initial {
		q, ok := position[v]
		if !ok {
			continue
		}
		b := before[q]
		best := query(max(0, b), q)
		if b < 0 {
			best = max(best, 0)
		}
		if best < 0 {
			continue
		}
		at, value := q+size, best+1
		if tree[at] >= value {
			continue
		}
		tree[at] = value
		for at >>= 1; at > 0; at >>= 1 {
			tree[at] = max(tree[2*at], tree[2*at+1])
		}
	}
	matched := query(max(0, last), n)
	if last < 0 {
		matched = max(matched, 0)
	}
	if matched >= 0 {
		fmt.Println(n - matched)
	} else {
		fmt.Println(-1)
	}
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
